^<]*)</td>', line)\n                # tds[0] = month\n                # tds[1-3] = 1970 data\n                # tds[4-6] = 1973 data\n                # tds[7-9] = 1976 data  \n                # tds[10-12] = 1979 data\n                if len(tds) >= 11:\n                    # Treasury bonds at index 10\n                    treasury = tds[10].strip()\n                    treasury = re.sub(r'\\s*\\d+/$', '', treasury)\n                    # Corporate bonds at index 11\n                    corp = tds[11].strip()\n                    corp = re.sub(r'\\s*\\d+/$', '', corp)\n                    \n                    try:\n                        treasury_1979.append(float(treasury))\n                        corp_1979.append(float(corp))\n                        print(f\"{m}: Treasury={treasury}, Corporate={corp}\")\n                    except:\n                        print(f\"Error parsing: Treasury={treasury}, Corp={corp}\")\n                break\n\nprint(f\"\\n1979 Treasury yields: {treasury_1979}\")\nprint(f\"1979 Corporate yields: {corp_1979}\")\nprint(f\"Count: {len(treasury_1979)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
